import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"💡 学习建议","description":"先定数据模型再写代码:多会话 / 多租户的表结构定错了,后面全是迁移","frontmatter":{},"headers":[],"relativePath":"agent/学习计划/项目C-端到端应用/14-study-tips.md","filePath":"agent/学习计划/项目C-端到端应用/14-study-tips.md","lastUpdated":1793932732000}'),l={name:"agent/学习计划/项目C-端到端应用/14-study-tips.md"};function i(s,t,n,d,c,g){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="💡-学习建议" tabindex="-1">💡 学习建议 <a class="header-anchor" href="#💡-学习建议" aria-label="Permalink to &quot;💡 学习建议&quot;">​</a></h1><ol><li><strong>先定数据模型再写代码</strong>:多会话 / 多租户的表结构定错了,后面全是迁移</li><li><strong>配置全部走环境变量</strong>:API Key、数据库连接串一律外置,不要硬编码</li><li><strong>文档上传要限流和大小限制</strong>:别让一次上传打满内存</li><li><strong>CI 要跑测试再出镜像</strong>:镜像构建很慢,先测后构</li><li><strong>数据库迁移纳入版本管理</strong>:用 Alembic 之类的工具,不要手写 DDL</li><li><strong>上线前演练一次回滚</strong>:没演练过的回滚方案等于没有</li><li>完成后回 <a href="/agent/学习计划/9-学习进度跟踪">进度跟踪页</a> 打卡</li></ol><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>核心建议:<strong>先打通主链路再补工程化</strong>;每一步都留一份可运行的截图或日志。</li><li>调试技巧:用 <code>docker compose</code> 一键起依赖;把请求的 trace_id 打到日志里,便于串联前后端问题。</li><li>一定要自己踩一次坑:<strong>索引超时、JWT 过期未刷新、容器里连不上数据库、CI 里密钥没配</strong>。</li><li>部署一次到免费平台(Cloudflare/Vercel/Render),能暴露大量本地看不出的环境问题。</li><li>面试加分:讲「<strong>我把三个项目串成了一条线:A 提供检索、B 提供编排、C 提供交付</strong>」,这比三个孤立项目强得多。</li></ul>',4)])])}const u=e(l,[["render",i]]);export{p as __pageData,u as default};
